/* 把 USART1 恢复到上电默认状态 */
USART_DeInit(USART1);

/* 复位会关掉外设使能位，之后必须重新初始化才能用 */
USART_Init(USART1, &USART_InitStructure);
USART_Cmd(USART1, ENABLE);

USART_InitTypeDef USART_InitStructure;
GPIO_InitTypeDef GPIO_InitStructure;

/* 1. 开时钟：GPIOA 与 USART1 都在 APB2 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_USART1, ENABLE);

/* 2. TX = PA9，必须配成复用推挽 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_9;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 3. RX = PA10，配成浮空输入或上拉输入 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_10;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 4. 串口参数：先填默认值再改，避免结构体里是随机值 */
USART_StructInit(&USART_InitStructure);
USART_InitStructure.USART_BaudRate = 115200;
USART_InitStructure.USART_WordLength = USART_WordLength_8b;
USART_InitStructure.USART_StopBits = USART_StopBits_1;
USART_InitStructure.USART_Parity = USART_Parity_No;
USART_InitStructure.USART_Mode = USART_Mode_Rx | USART_Mode_Tx;
USART_InitStructure.USART_HardwareFlowControl = USART_HardwareFlowControl_None;
USART_Init(USART1, &USART_InitStructure);

/* 5. 最后一定要使能，否则收发都不工作 */
USART_Cmd(USART1, ENABLE);

USART_InitTypeDef USART_InitStructure;

USART_StructInit(&USART_InitStructure);        /* 先填默认值 */
USART_InitStructure.USART_BaudRate = 115200;   /* 默认是 9600，必须改 */
USART_Init(USART1, &USART_InitStructure);

USART_ClockInitTypeDef USART_ClockInitStructure;

/* 同步模式：USART1 在 SCLK（PA8）上输出时钟 */
USART_ClockStructInit(&USART_ClockInitStructure);
USART_ClockInitStructure.USART_Clock = USART_Clock_Enable;
USART_ClockInitStructure.USART_CPOL = USART_CPOL_Low;
USART_ClockInitStructure.USART_CPHA = USART_CPHA_1Edge;
USART_ClockInitStructure.USART_LastBit = USART_LastBit_Disable;
USART_ClockInit(USART1, &USART_ClockInitStructure);

USART_ClockInitTypeDef USART_ClockInitStructure;

USART_ClockStructInit(&USART_ClockInitStructure);
USART_ClockInitStructure.USART_Clock = USART_Clock_Enable;   /* 再改成需要的值 */
USART_ClockInit(USART1, &USART_ClockInitStructure);

/* 初始化序列的最后一步 */
USART_Cmd(USART1, ENABLE);

/* 需要临时改配置时：先关、再改、再开 */
USART_Cmd(USART1, DISABLE);
USART_Init(USART1, &USART_InitStructure);
USART_Cmd(USART1, ENABLE);

NVIC_InitTypeDef NVIC_InitStructure;

/* 1. 打开串口侧的接收中断使能位 */
USART_ITConfig(USART1, USART_IT_RXNE, ENABLE);

/* 2. NVIC 也必须配，只调 USART_ITConfig 是进不了中断的 */
NVIC_InitStructure.NVIC_IRQChannel = USART1_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 1;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

/* 3. 最后使能串口 */
USART_Cmd(USART1, ENABLE);

/* 4. 中断服务函数 */
void USART1_IRQHandler(void)
{
  if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET)
  {
    uint8_t ch = (uint8_t)USART_ReceiveData(USART1);
    /* 处理 ch ... */
  }
}

DMA_InitTypeDef DMA_InitStructure;

/* 1. 开 DMA1 时钟 */
RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA1, ENABLE);

/* 2. 配置 USART1_TX 对应的 DMA1 通道 4 */
DMA_DeInit(DMA1_Channel4);
DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&USART1->DR;
DMA_InitStructure.DMA_MemoryBaseAddr = (uint32_t)txBuffer;
DMA_InitStructure.DMA_DIR = DMA_DIR_PeripheralDST;
DMA_InitStructure.DMA_BufferSize = len;
DMA_InitStructure.DMA_PeripheralInc = DMA_PeripheralInc_Disable;
DMA_InitStructure.DMA_MemoryInc = DMA_MemoryInc_Enable;
DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_Byte;
DMA_InitStructure.DMA_MemoryDataSize = DMA_MemoryDataSize_Byte;
DMA_InitStructure.DMA_Mode = DMA_Mode_Normal;
DMA_InitStructure.DMA_Priority = DMA_Priority_Medium;
DMA_InitStructure.DMA_M2M = DMA_M2M_Disable;
DMA_Init(DMA1_Channel4, &DMA_InitStructure);

/* 3. 先打开 USART 的 DMA 发送请求，再启动 DMA，顺序反了会丢第一个字节 */
USART_DMACmd(USART1, USART_DMAReq_Tx, ENABLE);
DMA_Cmd(DMA1_Channel4, ENABLE);

/* 多机通信：本机地址设为 3 */
USART_SetAddress(USART2, 0x03);
USART_WakeUpConfig(USART2, USART_WakeUp_AddressMark);
USART_ReceiverWakeUpCmd(USART2, ENABLE);   /* 进入静默，等待地址匹配唤醒 */

USART_ReceiverWakeUpCmd(USART2, ENABLE);    /* 进入静默，等待被唤醒 */
/* ... 收到匹配的地址帧后硬件自动唤醒 ... */
USART_ReceiverWakeUpCmd(USART2, DISABLE);   /* 退出静默 */

USART_LINBreakDetectLengthConfig(USART2, USART_LINBreakDetectLength_11b);
USART_LINCmd(USART2, ENABLE);
USART_ITConfig(USART2, USART_IT_LBD, ENABLE);   /* 检测到 break 时进中断 */

/* LIN 主机：先开 LIN 模式，再发同步间隔 */
USART_LINCmd(USART2, ENABLE);
USART_SendBreak(USART2);

/* 阻塞方式发送一个字节 */
void USART1_SendByte(uint8_t ch)
{
  /* 必须等发送数据寄存器空，否则会覆盖上一次的数据 */
  while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET);
  USART_SendData(USART1, ch);
}

/* 发送字符串，末尾等真正发完 */
void USART1_SendString(char *str)
{
  while (*str != 0)
  {
    USART1_SendByte((uint8_t)(*str));
    str++;
  }
  /* TXE 只说明寄存器空，TC 才说明最后一个位也发到线上了 */
  while (USART_GetFlagStatus(USART1, USART_FLAG_TC) == RESET);
}

uint8_t ch;

/* 方式一：查询接收 */
while (USART_GetFlagStatus(USART1, USART_FLAG_RXNE) == RESET);
ch = (uint8_t)USART_ReceiveData(USART1);

/* 方式二：中断接收（推荐，不占用主循环） */
void USART1_IRQHandler(void)
{
  if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET)
  {
    /* 读 DR 的同时自动清掉 RXNE，不需要手动清标志 */
    ch = (uint8_t)USART_ReceiveData(USART1);
  }
}

/* LIN 主机发送同步间隔 */
USART_LINCmd(USART2, ENABLE);
USART_SendBreak(USART2);
/* 后面通常紧跟同步字节 0x55 */
while (USART_GetFlagStatus(USART2, USART_FLAG_TXE) == RESET);
USART_SendData(USART2, 0x55);

/* 智能卡模式：保护时间 0，预分频按卡片时钟要求设置 */
USART_SmartCardCmd(USART2, ENABLE);
USART_SetGuardTime(USART2, 0);
USART_SetPrescaler(USART2, 5);

/* IrDA 低功耗模式 */
USART_IrDAConfig(USART2, USART_IrDAMode_LowPower);
USART_IrDACmd(USART2, ENABLE);
USART_SetPrescaler(USART2, 1);

USART_SmartCardCmd(USART2, ENABLE);
USART_SetGuardTime(USART2, 0);
USART_SetPrescaler(USART2, 5);

/* 单线半双工：只用 PA9 一根线 */
USART_HalfDuplexCmd(USART1, ENABLE);

/* 发送，发完等 TC 再收 */
while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET);
USART_SendData(USART1, 0x55);
while (USART_GetFlagStatus(USART1, USART_FLAG_TC) == RESET);

/* 接收 */
while (USART_GetFlagStatus(USART1, USART_FLAG_RXNE) == RESET);
ch = (uint8_t)USART_ReceiveData(USART1);

/* 必须先开 8 倍过采样，再 USART_Init，BRR 才会按 8 倍采样计算 */
USART_OverSampling8Cmd(USART1, ENABLE);
USART_Init(USART1, &USART_InitStructure);

/* 低功耗红外：先选模式，再开 IrDA，最后设预分频 */
USART_IrDAConfig(USART2, USART_IrDAMode_LowPower);
USART_IrDACmd(USART2, ENABLE);
USART_SetPrescaler(USART2, 1);

uint8_t ch;

/* 查询方式发一个字节 */
while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET);
USART_SendData(USART1, 0x5A);

/* 确认整帧发完：切 RS485 收发方向、进低功耗、复位前必须等这个 */
while (USART_GetFlagStatus(USART1, USART_FLAG_TC) == RESET);

/* 查询方式收一个字节 */
while (USART_GetFlagStatus(USART1, USART_FLAG_RXNE) == RESET);
ch = (uint8_t)USART_ReceiveData(USART1);

/* 清 TC 标志 */
USART_ClearFlag(USART1, USART_FLAG_TC);

/* 清 ORE 溢出标志：必须是「先读 SR，再读 DR」的序列 */
if (USART_GetFlagStatus(USART1, USART_FLAG_ORE) != RESET)   /* 这一步读的是 SR */
{
  (void)USART_ReceiveData(USART1);                          /* 这一步读的是 DR，ORE 才被清掉 */
}

void USART1_IRQHandler(void)
{
  uint8_t ch;

  /* 接收中断：RXNE 置位说明收到一个字节 */
  if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET)
  {
    ch = (uint8_t)USART_ReceiveData(USART1);   /* 读 DR 会自动清 RXNE */
    /* 处理 ch ... */
  }

  /* 空闲中断：一帧结束，必须靠读 DR 清标志 */
  if (USART_GetITStatus(USART1, USART_IT_IDLE) != RESET)
  {
    (void)USART_ReceiveData(USART1);
  }

  /* 溢出错误：不清掉会反复进中断 */
  if (USART_GetITStatus(USART1, USART_IT_ORE) != RESET)
  {
    (void)USART_ReceiveData(USART1);
  }
}

void USART1_IRQHandler(void)
{
  /* TC 中断：可以用 ClearITPendingBit 清 */
  if (USART_GetITStatus(USART1, USART_IT_TC) != RESET)
  {
    USART_ClearITPendingBit(USART1, USART_IT_TC);
  }

  /* RXNE 中断：读 DR 自动清，不需要再调 ClearITPendingBit */
  if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET)
  {
    (void)USART_ReceiveData(USART1);
  }
}
